import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Row, Snapshot } from '../types'

const snapshot = atom({ plugin: 'context-bar', key: 'snapshot' } as const, null)

// Legend order and colors, matched against /context's category names.
const CATEGORIES = [
  { label: 'system prompt', match: 'system prompt', color: '#7095d1' },
  { label: 'tools', match: 'system tools', color: '#5cc8c8' },
  { label: 'mcp tools', match: 'mcp tools', color: '#a78bfa' },
  { label: 'agents', match: 'agents', color: '#8fd17f' },
  { label: 'memory files', match: 'memory', color: '#e5c07b' },
  { label: 'skills', match: 'skills', color: '#f0a6c8' },
  { label: 'messages', match: 'messages', color: '#e2714e' },
]
const FREE = '#3a3a4c'
const MARKER = '#f5b942'
const ACCENT = '#d97757'
const BADGE = '#8fd17f'

export const fmt = (n: number): string => {
  const trim = (x: number) => x.toFixed(1).replace(/\.0$/, '')
  if (n >= 1e6) return `${trim(n / 1e6)}M`
  if (n >= 1e4) return `${Math.round(n / 1000)}k`
  if (n >= 1000) return `${trim(n / 1000)}k`
  return String(n)
}

export const pct = (n: number, of: number): number =>
  n > 0 ? Math.max(1, Math.round((n / of) * 100)) : 0

async function refresh($: EngineInterface) {
  try {
    const { context } = await $.session.usage({ breakdown: 'summary' })
    const b = context.breakdown
    if (!b) return
    const used = b.categories.filter(c => c.kind === 'used')
    const rows: Row[] = CATEGORIES.map(({ label, match, color }) => ({
      label,
      color,
      tokens: used
        .filter(c => c.name.toLowerCase().includes(match))
        .reduce((sum, c) => sum + c.tokens, 0),
    }))
    const total = b.totalTokens
    const free =
      b.categories.find(c => c.kind === 'free')?.tokens ?? Math.max(0, context.window - total)
    const snap: Snapshot = {
      used: total,
      window: context.window,
      compactAt: b.isAutoCompactEnabled ? (b.autoCompactThreshold ?? null) : null,
      rows,
      free,
    }
    await update($, snapshot, () => snap)
  } catch {
    // ponytail: usage can fail before a session is bound; the next event retries
  }
}

// One bar cell per slot: each category gets at least one cell when non-empty.
export const barCells = (s: Snapshot, width: number): string[] => {
  const cells: string[] = []
  for (const r of s.rows) {
    const n = r.tokens > 0 ? Math.max(1, Math.round((r.tokens / s.window) * width)) : 0
    for (let i = 0; i < n && cells.length < width; i++) cells.push(r.color)
  }
  while (cells.length < width) cells.push(FREE)
  if (s.compactAt !== null) {
    cells[Math.min(width - 1, Math.floor((s.compactAt / s.window) * width))] = MARKER
  }
  return cells
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await refresh($)
    return r
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId === undefined) await refresh($)
    return r
  })

  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    void refresh($)
    return r
  })

  on('session.compact', async ($, e, next) => {
    const r = await next(e)
    await refresh($)
    return r
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const s = await read($, snapshot)
    if (e.props.hasSurvey || s === null) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    const width = Math.min(e.props.bodyColumns, 56)
    const inner = width - 4
    const half = Math.floor(inner / 2)

    // Merge equal neighbours into runs so the bar is a handful of Texts.
    const runs: { color: string; n: number }[] = []
    for (const c of barCells(s, inner)) {
      const last = runs.at(-1)
      if (last && last.color === c) last.n++
      else runs.push({ color: c, n: 1 })
    }

    const legend = [
      ...s.rows,
      { label: 'free', tokens: s.free, color: FREE },
    ]
    const pairs = []
    for (let i = 0; i < legend.length; i += 2) pairs.push(legend.slice(i, i + 2))

    return (
      <Box flexDirection="column" borderStyle="round" borderColor="#3b3b4f" paddingX={1} width={width}>
        <Box justifyContent="space-between">
          <Text wrap="truncate">
            <Text color={ACCENT}>◆ </Text>
            <Text bold>context window {fmt(s.used)}</Text>
            <Text dimColor>
              {' '}of {fmt(s.window)}
              {s.compactAt !== null ? ` · compacts at ${fmt(s.compactAt)}` : ''}
            </Text>
          </Text>
          <Text backgroundColor={BADGE} color="#1a1b26" bold>
            {` ${pct(s.used, s.window)}% `}
          </Text>
        </Box>
        <Text>
          {runs.map((r, i) => (
            <Text key={`b${i}`} color={r.color} backgroundColor={r.color === MARKER ? FREE : undefined}>
              {(r.color === MARKER ? '▕' : '█').repeat(r.n)}
            </Text>
          ))}
        </Text>
        {pairs.map((pair, i) => (
          <Box key={`l${i}`}>
            {pair.map(r => (
              <Box key={r.label} width={half}>
                <Text wrap="truncate">
                  <Text color={r.color}>■ </Text>
                  {r.label} <Text bold>{fmt(r.tokens)}</Text>
                  {r.label === 'free' ? '' : <Text dimColor> {pct(r.tokens, s.window)}%</Text>}
                </Text>
              </Box>
            ))}
          </Box>
        ))}
      </Box>
    )
  })
}

