export type Row = { label: string; tokens: number; color: string }
export type Snapshot = { used: number; window: number; compactAt: number | null; rows: Row[]; free: number }

declare module 'claude-code' {
  interface PluginState {
    'context-bar': { snapshot: Snapshot | null }
  }
}
